const integrationId = $('Separar por Integração').first().json.id;
const count = $('Preparar Records1').first().json.count ?? 0;
return [{ json: { integration_id: integrationId, count } }];

const item = $('Preparar Records1').item.json;
const records = item.records || [];
const byDate = {};

for (const r of records) {
  if (!r.date) continue;
  if (!byDate[r.date]) {
    byDate[r.date] = {
      client_id:        r.client_id,
      organization_id:  r.organization_id,
      date:             r.date,
      total_spend:      0,
      total_leads:      0,
      total_sales:      0,
      total_revenue:    0,
      total_impressions:0,
      total_clicks:     0
    };
  }
  byDate[r.date].total_spend       += r.spend       || 0;
  byDate[r.date].total_leads       += r.leads       || 0;
  byDate[r.date].total_sales       += r.sales       || 0;
  byDate[r.date].total_revenue     += r.revenue     || 0;
  byDate[r.date].total_impressions += r.impressions || 0;
  byDate[r.date].total_clicks      += r.clicks      || 0;
}

const daily_rows = Object.values(byDate).map(d => ({
  ...d,
  cpl:  d.total_leads  > 0 ? +(d.total_spend / d.total_leads).toFixed(4)   : 0,
  cpa:  d.total_sales  > 0 ? +(d.total_spend / d.total_sales).toFixed(4)   : 0,
  roas: d.total_spend  > 0 ? +(d.total_revenue / d.total_spend).toFixed(4) : 0
}));

return [{ json: { daily_rows, integration_id: item.integration_id, count: item.count } }];

// Garante que os records chegam como array independente do formato de entrada
// O IF pode passar um item { records: [...] } ou múltiplos itens individuais
const allItems = $input.all();
let records = [];
let integration_id = null;
let client_id = null;
let organization_id = null;
let count = 0;

if (allItems.length === 1 && Array.isArray(allItems[0].json.records)) {
  // Formato esperado: um item com array records
  records = allItems[0].json.records;
  integration_id = allItems[0].json.integration_id;
  client_id = allItems[0].json.client_id;
  organization_id = allItems[0].json.organization_id;
  count = allItems[0].json.count ?? records.length;
} else {
  // Múltiplos itens individuais (cada item é um record)
  records = allItems.map(i => i.json).filter(r => r.client_id);
  if (records.length > 0) {
    integration_id = allItems[0].json.integration_id ?? null;
    client_id = records[0].client_id;
    organization_id = records[0].organization_id;
  }
  count = records.length;
}

return [{ json: { records, integration_id, client_id, organization_id, count } }];

