const ctx = $('Resolver Organização').first().json;

// Pega TODOS os itens do input (não só o primeiro)
const allItems = $input.all();
const rawItems = allItems.map(i => i.json);

// Normaliza: suporta array direto, wrapper {data: []}, ou item único
let integrations = [];
for (const item of rawItems) {
  if (Array.isArray(item)) {
    integrations.push(...item);
  } else if (Array.isArray(item?.data)) {
    integrations.push(...item.data);
  } else if (item?.id) {
    integrations.push(item);
  }
}

// Filtra apenas registros com account_id e access_token OU refresh_token (Google usa refresh_token)
integrations = integrations.filter(i => i.id && i.account_id && (i.access_token || i.refresh_token));

// Aplica filtro por integration_id ou client_id se vieram no payload
// Garante que null/"null"/undefined são tratados como ausentes
const integrationId = ctx.integration_id && ctx.integration_id !== 'null' ? ctx.integration_id : null;
const clientId = ctx.client_id && ctx.client_id !== 'null' ? ctx.client_id : null;

if (integrationId) {
  integrations = integrations.filter(i => i.id === integrationId);
} else if (clientId) {
  integrations = integrations.filter(i => i.client_id === clientId);
}

if (integrations.length === 0) {
  return [{ json: { _empty: true, message: 'Nenhuma integração ativa encontrada' } }];
}

return integrations.map(i => ({ json: { ...i, organization_id: ctx.organization_id } }));

// Determina o organization_id: vem do body (webhook) ou da env var (schedule)
const input = $input.first()?.json ?? {};
// n8n 2.x: webhook coloca o body em input.body; schedule chega direto
const body = (input.body && typeof input.body === 'object') ? input.body : input;
const orgId = body.organization_id ?? $env.ORGANIZATION_ID ?? '';
const clientId = body.client_id ?? null;
const integrationId = body.integration_id ?? null;

if (!orgId) throw new Error('organization_id nao encontrado no payload nem em ORGANIZATION_ID env var');

return [{ json: { organization_id: orgId, client_id: clientId, integration_id: integrationId } }];

const integration = $('Roteador por Plataforma1').first().json;
const insights    = $('Meta Ads API1').first().json;
const objetivos   = $('Meta Campanhas (Objetivos)1').first().json;

const rows = insights.data || [];
if (rows.length === 0) return [{ json: { _skip: true, integration_id: integration.id } }];

const OBJECTIVE_LABELS = {
  OUTCOME_AWARENESS:     'Reconhecimento',
  OUTCOME_TRAFFIC:       'Tráfego',
  OUTCOME_ENGAGEMENT:    'Engajamento',
  OUTCOME_LEADS:         'Geração de Leads',
  OUTCOME_APP_PROMOTION: 'Promoção de App',
  OUTCOME_SALES:         'Vendas',
  REACH:                 'Alcance',
  BRAND_AWARENESS:       'Reconhecimento de Marca',
  VIDEO_VIEWS:           'Visualizações de Vídeo',
  LINK_CLICKS:           'Cliques no Link',
  POST_ENGAGEMENT:       'Engajamento com Post',
  PAGE_LIKES:            'Curtidas na Página',
  EVENT_RESPONSES:       'Respostas a Eventos',
  MESSAGES:              'Mensagens',
  CONVERSIONS:           'Conversões',
  PRODUCT_CATALOG_SALES: 'Vendas do Catálogo',
  STORE_VISITS:          'Visitas à Loja',
};

const OBJECTIVE_ACTION_MAP = {
  OUTCOME_TRAFFIC:       ['landing_page_view', 'link_click'],
  OUTCOME_ENGAGEMENT:    ['post_engagement', 'page_engagement', 'post_reaction', 'comment', 'post'],
  OUTCOME_LEADS:         ['lead', 'leadgen_grouped'],
  OUTCOME_SALES:         ['purchase', 'omni_purchase'],
  OUTCOME_APP_PROMOTION: ['app_install', 'mobile_app_install'],
  VIDEO_VIEWS:           ['video_view'],
  LINK_CLICKS:           ['link_click'],
  POST_ENGAGEMENT:       ['post_engagement'],
  MESSAGES:              ['onsite_conversion.messaging_conversation_started_7d'],
  CONVERSIONS:           ['purchase', 'omni_purchase'],
  PRODUCT_CATALOG_SALES: ['purchase', 'omni_purchase'],
};

const OBJECTIVE_METRIC_LABEL = {
  OUTCOME_TRAFFIC:       'Visualizações da Pág. de Destino',
  OUTCOME_AWARENESS:     'Alcance',
  OUTCOME_ENGAGEMENT:    'Engajamentos',
  OUTCOME_LEADS:         'Leads',
  OUTCOME_SALES:         'Compras',
  OUTCOME_APP_PROMOTION: 'Instalações de App',
  VIDEO_VIEWS:           'ThruPlays',
  REACH:                 'Alcance',
  LINK_CLICKS:           'Cliques no Link',
  POST_ENGAGEMENT:       'Engajamentos com Post',
  MESSAGES:              'Conversas Iniciadas',
  CONVERSIONS:           'Conversões',
  PRODUCT_CATALOG_SALES: 'Vendas do Catálogo',
};

function getObjectiveMetric(objective, actions, row) {
  actions = actions || [];
  row = row || {};
  if (!objective) return null;

  if (objective === 'VIDEO_VIEWS') {
    const thruplay = actions.find(a => a.action_type === 'video_view');
    if (thruplay) return parseInt(thruplay.value || 0);
    const v30 = (row.video_30_sec_watched_actions || []).find(a => a.action_type === 'video_view');
    if (v30) return parseInt(v30.value || 0);
    return 0;
  }

  // Reach e impressions vêm como campos diretos, não dentro de actions[]
  if (objective === 'OUTCOME_AWARENESS' || objective === 'REACH') {
    return parseInt(row.reach || 0);
  }

  const relevantTypes = OBJECTIVE_ACTION_MAP[objective] || [];
  for (const type of relevantTypes) {
    const found = actions.find(a => a.action_type === type);
    if (found) return parseInt(found.value || 0);
  }

  return null;
}

// Formato: { data: [ { id, name, objective }, ... ] }
const objectiveMap = {};
for (const c of (objetivos.data || [])) {
  if (c.id && c.objective) {
    objectiveMap[c.id] = c.objective;
  }
}

const records = rows.map(c => {
  const rawObjective   = objectiveMap[c.campaign_id] ?? null;
  const objectiveLabel = rawObjective ? (OBJECTIVE_LABELS[rawObjective] ?? rawObjective) : null;

  const actions      = c.actions || [];
  const actionValues = c.action_values || [];

  const objectiveMetricValue = getObjectiveMetric(rawObjective, actions, c);
  const objectiveMetricLabel = rawObjective ? (OBJECTIVE_METRIC_LABEL[rawObjective] ?? null) : null;

  return {
    client_id:              integration.client_id,
    organization_id:        integration.organization_id,
    platform:               'meta',
    date:                   c.date_start,
    campaign_id:            c.campaign_id,
    campaign_name:          c.campaign_name || 'Sem nome',
    objective:              objectiveLabel,
    objective_metric_label: objectiveMetricLabel,
    objective_metric_value: objectiveMetricValue,
    spend:                  parseFloat(c.spend || 0),
    impressions:            parseInt(c.impressions || 0),
    reach:                  parseInt(c.reach || 0),
    clicks:                 parseInt(c.clicks || 0),
    leads:                  parseInt(actions.find(a => a.action_type === 'lead')?.value || 0),
    sales:                  parseInt(actions.find(a => a.action_type === 'purchase')?.value || 0),
    revenue:                parseFloat(actionValues.find(a => a.action_type === 'purchase')?.value || 0),
  };
});

return records.map(record => ({ 
  json: { ...record, integration_id: integration.id } 
}));

const integration = $('Roteador por Plataforma1').item.json;
const tokenResp = $input.item.json;
const accessToken = tokenResp.access_token;
if (!accessToken) {
  const errMsg = tokenResp.error_description || tokenResp.error || 'unknown';
  return [{ json: { _skip: true, _error: 'Falha ao renovar token Google: ' + errMsg, integration_id: integration.id } }];
}
return [{ json: { ...integration, access_token: accessToken } }];

