const integration = $('Roteador por Plataforma1').item.json;
const response = $input.item.json;

if (response.error || response.errors) {
  const msg = response.error?.message || JSON.stringify(response.errors);
  return [{ json: { _skip: true, _error: msg, integration_id: integration.id } }];
}

const results = response.results || [];
if (results.length === 0) return [{ json: { _skip: true, integration_id: integration.id } }];

const records = results.map(r => ({
  client_id:       integration.client_id,
  organization_id: integration.organization_id,
  platform:        'google',
  date:            r.segments?.date,
  campaign_name:   r.campaign?.name || 'Sem nome',
  spend:           (r.metrics?.costMicros || 0) / 1_000_000,
  impressions:     parseInt(r.metrics?.impressions || 0),
  clicks:          parseInt(r.metrics?.clicks || 0),
  leads:           0,
  sales:           Math.round(parseFloat(r.metrics?.conversions || 0)),
  revenue:         parseFloat(r.metrics?.conversionsValue || 0)
}));

return [{ json: { records, integration_id: integration.id, client_id: integration.client_id, organization_id: integration.organization_id, count: records.length } }];

// Recebe o array de integrações e extrai apenas os campos necessários
const integrations = $input.all().map(item => item.json);

return integrations.map(integration => ({
  json: {
    integration_id:              integration.id,
    organization_id: integration.organization_id,
    client_id:       integration.client_id,
    platform:        integration.platform,
  }
}));
